package org.apache.commons.math3.linear;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math3.exception.MathArithmeticException;
import org.apache.commons.math3.exception.NotPositiveException;
import org.apache.commons.math3.exception.util.LocalizedFormats;
import org.apache.commons.math3.util.FastMath;
import org.apache.commons.math3.util.OpenIntToDoubleHashMap.Iterator;
import org.apache.commons.math3.util.OpenIntToDoubleHashMap;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for OpenMapRealVector.ebeDivide
 */
public class OpenMapRealVector_ebeDivide_TriageGen1Test {

    private static final double EPSILON = 1e-10;

    @Test
    public void testEbeDivideNormalCase() {
        double[] values1 = {1.0, 2.0, 0.0, 4.0};
        double[] values2 = {2.0, 2.0, 5.0, 1.0};
        OpenMapRealVector v1 = new OpenMapRealVector(values1);
        OpenMapRealVector v2 = new OpenMapRealVector(values2);

        OpenMapRealVector result = v1.ebeDivide(v2);

        // 1.0 / 2.0 = 0.5
        // 2.0 / 2.0 = 1.0
        // 0.0 / 5.0 = 0.0 (Since index 2 is not in v1's entries, it remains 0.0)
        // 4.0 / 1.0 = 4.0
        Assert.assertEquals(4, result.getDimension());
        Assert.assertEquals(0.5, result.getEntry(0), EPSILON);
        Assert.assertEquals(1.0, result.getEntry(1), EPSILON);
        Assert.assertEquals(0.0, result.getEntry(2), EPSILON);
        Assert.assertEquals(4.0, result.getEntry(3), EPSILON);
    }

    @Test
    public void testEbeDivideWithZeroDivisor() {
        double[] values1 = {1.0, 4.0};
        double[] values2 = {2.0, 0.0};
        OpenMapRealVector v1 = new OpenMapRealVector(values1);
        OpenMapRealVector v2 = new OpenMapRealVector(values2);

        OpenMapRealVector result = v1.ebeDivide(v2);

        Assert.assertEquals(0.5, result.getEntry(0), EPSILON);
        // 4.0 / 0.0 should result in Infinity
        Assert.assertTrue(Double.isInfinite(result.getEntry(1)));
    }

    @Test
    public void testEbeDivideWithNaN() {
        double[] values1 = {1.0, 4.0};
        double[] values2 = {2.0, Double.NaN};
        OpenMapRealVector v1 = new OpenMapRealVector(values1);
        OpenMapRealVector v2 = new OpenMapRealVector(values2);

        OpenMapRealVector result = v1.ebeDivide(v2);

        Assert.assertEquals(0.5, result.getEntry(0), EPSILON);
        Assert.assertTrue(Double.isNaN(result.getEntry(1)));
    }

    @Test(expected = DimensionMismatchException.class)
    public void testEbeDivideDimensionMismatch() {
        OpenMapRealVector v1 = new OpenMapRealVector(new double[]{1.0, 2.0});
        OpenMapRealVector v2 = new OpenMapRealVector(new double[]{1.0, 2.0, 3.0});
        v1.ebeDivide(v2);
    }

    @Test
    public void testEbeDivideSparseEntries() {
        // Test case specifically targeting the MATH-803 comment logic:
        // If this[i] = 0 and v[i] = 0, result should be 0, not NaN.
        // In OpenMapRealVector, if this[i] is 0, it's not in the entries iterator.

        OpenMapRealVector v1 = new OpenMapRealVector(3);
        v1.setEntry(0, 10.0);
        // v1.getEntry(1) is 0.0
        v1.setEntry(2, 5.0);

        OpenMapRealVector v2 = new OpenMapRealVector(3);
        v2.setEntry(0, 2.0);
        v2.setEntry(1, 0.0); // v[1] is 0.0
        v2.setEntry(2, 1.0);

        OpenMapRealVector result = v1.ebeDivide(v2);

        Assert.assertEquals(5.0, result.getEntry(0), EPSILON);
        // Since v1[1] is 0, the iterator skips index 1. 
        // The entry in 'res' (copied from v1) for index 1 is 0.0.
        // Therefore, even though v2[1] is 0, result[1] remains 0.0, not NaN.
        Assert.assertEquals(0.0, result.getEntry(1), EPSILON);
        Assert.assertEquals(5.0, result.getEntry(2), EPSILON);
    }

    @Test
    public void testEbeDivideEmpty() {
        OpenMapRealVector v1 = new OpenMapRealVector(5);
        OpenMapRealVector v2 = new OpenMapRealVector(new double[]{1, 2, 3, 4, 5});

        OpenMapRealVector result = v1.ebeDivide(v2);

        Assert.assertEquals(5, result.getDimension());
        for (int i = 0; i < 5; i++) {
            Assert.assertEquals(0.0, result.getEntry(i), EPSILON);
        }
    }
}
